(()=>{'use strict';const lat=32.3838028,lon=51.5091785,map=document.getElementById('map'),tiles=document.getElementById('tiles'),error=document.getElementById('error');let zoom=16,generation=0;
function draw(){const g=++generation,n=2**zoom,x=(lon+180)/360*n*256,r=lat*Math.PI/180,y=(1-Math.log(Math.tan(r)+1/Math.cos(r))/Math.PI)/2*n*256,w=map.clientWidth,h=map.clientHeight;tiles.replaceChildren();error.hidden=true;let failures=0,success=0;for(let tx=Math.floor((x-w/2)/256);tx<=Math.floor((x+w/2)/256);tx++)for(let ty=Math.floor((y-h/2)/256);ty<=Math.floor((y+h/2)/256);ty++){const img=new Image();img.alt='';img.draggable=false;img.style.left=(tx*256-x+w/2)+'px';img.style.top=(ty*256-y+h/2)+'px';img.onload=()=>{if(g!==generation)return;success++;error.hidden=true};img.onerror=()=>{if(g!==generation)return;failures++;if(!success&&failures>=3)error.hidden=false};img.src='https://tile.openstreetmap.org/'+zoom+'/'+tx+'/'+ty+'.png';tiles.append(img)}document.getElementById('plus').disabled=zoom>=18;document.getElementById('minus').disabled=zoom<=12;}
document.getElementById('plus').onclick=()=>{if(zoom<18){zoom++;draw()}};document.getElementById('minus').onclick=()=>{if(zoom>12){zoom--;draw()}};let frame;window.addEventListener('resize',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(draw)});draw();})();
